import json, html, math
from pathlib import Path

# The graphics and data are deliberately hypothetical rather than animal observations.
# Each panel is authored for its question; source leads require independent verification.
def text(x,y,t,size=13): return f'<text x="{x}" y="{y}" textAnchor="middle" fontSize="{size}" fill="var(--fg)">{html.escape(t)}</text>'
def line(x1,y1,x2,y2,color='var(--fg)',w=3): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" strokeWidth="{w}"/>'
def circle(x,y,r,color='var(--good)'): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{color}"/>'
def rect(x,y,w,h,color='var(--good)'): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="4" fill="{color}"/>'
def arrow(x1,y1,x2,y2,col='var(--good)'):
 d=math.hypot(x2-x1,y2-y1); ux=(x2-x1)/d; uy=(y2-y1)/d
 p1=(x2-9*ux+4*uy,y2-9*uy-4*ux);p2=(x2-9*ux-4*uy,y2-9*uy+4*ux)
 return line(x1,y1,x2,y2,col,3)+f'<path d="M{x2} {y2} L{p1[0]:.1f} {p1[1]:.1f} L{p2[0]:.1f} {p2[1]:.1f} Z" fill="{col}"/>'
def mouse(x,y):
 return f'<g transform="translate({x} {y})" stroke="var(--fg)" strokeWidth="2"><ellipse rx="13" ry="8" fill="var(--good)"/><circle cx="-9" cy="-7" r="4" fill="var(--good)"/><circle cx="5" cy="-2" r="1.6" fill="var(--fg)"/><path d="M-13 3 Q-22 0 -23 8" fill="none"/></g>'
def bird(x,y):
 return f'<g transform="translate({x} {y})" stroke="var(--fg)" strokeWidth="1.5"><ellipse rx="11" ry="8" fill="var(--good)"/><path d="M-4 0 Q1 8 6 0" fill="none"/><path d="M10 -1 L16 2 L10 4 Z" fill="var(--warn)"/><circle cx="6" cy="-3" r="1.2" fill="var(--fg)"/></g>'
def shark(x,y):
 return f'<g transform="translate({x} {y})" fill="var(--good)" stroke="var(--fg)" strokeWidth="1.5"><path d="M-23 0 Q-8 -12 12 -7 L21 0 L12 7 Q-8 12 -23 0 Z"/><path d="M-8 -7 L0 -16 L4 -8 M-22 -1 L-30 -10 L-29 9 Z"/><circle cx="14" cy="-2" r="1.4" fill="var(--fg)"/></g>'
def flower(x,y,center):
 return f'<g transform="translate({x} {y})" stroke="var(--fg)" strokeWidth="1"><ellipse cx="0" cy="-17" rx="10" ry="18" fill="var(--warn)"/><ellipse cx="17" cy="0" rx="18" ry="10" fill="var(--warn)"/><ellipse cx="0" cy="17" rx="10" ry="18" fill="var(--warn)"/><ellipse cx="-17" cy="0" rx="18" ry="10" fill="var(--warn)"/><circle r="10" fill="{center}"/></g>'
def panel(label,body): return text(76,19,label,13)+body
cases=[
 dict(id=406,slug='zoo-behavior-cue-food-pair',title='A sound before food',hook='An animal encounters two events in sequence.',q='In a toy study, food follows a bell. Later the bell alone elicits salivation. What does the later response illustrate?',opts=['A learned cue–food association','A change in the food','A new food reward'],why='In the first panel, bell and food appear together. In the later panel, the bell occurs alone and the stipulated salivation still appears. That pattern is consistent with a learned cue–food association; the diagrams are not real observations.',a=panel('Pairing',text(42,52,'Bell')+text(107,52,'Food')+arrow(43,67,107,67)+text(76,101,'Salivation')),b=panel('Later',text(40,52,'Bell')+arrow(58,66,107,66)+text(108,87,'Salivation')),rq='In a toy study, a light repeatedly precedes food. Later the light alone evokes a response. What may have been learned?',ro=['A light–food association','A change in the light bulb','A new food reward'],rw='The later response to the light is consistent with a learned association.'),
 dict(id=407,slug='zoo-behavior-action-consequence',title='A lever and a reward',hook='Actions can be followed by consequences.',q='In a toy trial, food follows a lever press. Which before-and-later counts would show an increase in pressing?',opts=['1 then 4 presses','4 then 1 press','2 then 2 presses'],why='The stipulated record shows one press before and four after the rewarded action. It illustrates a change in action frequency after a consequence; without further controls this tiny record does not establish why the change occurred.',a=panel('Earlier',rect(37,64,14,48)+circle(44,56,7)+mouse(100,61)+circle(112,80,4,'var(--warn)')+text(112,92,'food',11)+text(101,110,'1 press')),b=panel('Later',rect(37,64,14,48)+circle(44,56,7)+mouse(100,61)+text(101,104,'4 presses')),rq='A toy animal performs an action twice before a reward and five times later. What does the record compare?',ro=['Action frequency','Body temperature','Lever color'],rw='The stated counts compare how often the action occurs.'),
 dict(id=408,slug='zoo-behavior-response-after-practice',title='A response can change',hook='An initial response and a later response can differ.',q='In a toy test, response A stays the same across practice, while response B improves after practice. Which pattern is consistent with learning?',opts=['Response B','Response A','Both must be reflexes'],why='Panel A shows the same stipulated response on each trial. Panel B shows a response changing after practice. That change is consistent with learning, although fatigue, growth or other factors would need controls before concluding why.',a=panel('Response A',rect(28,82,24,27)+rect(64,82,24,27)+rect(100,82,24,27)+text(75,127,'Same')),b=panel('Response B',rect(28,95,24,14)+rect(64,82,24,27)+rect(100,68,24,41)+text(75,127,'Changes')),rq='A trained animal’s performance changes across practice. What is one possibility to investigate?',ro=['Learning','A perfectly unchanged response','A missing observation'],rw='A change after practice is consistent with learning but does not prove its cause.'),
 dict(id=413,slug='zoo-behavior-home-vector',title='Finding a way back',hook='A route can be summarized by a displacement.',q='In a toy map, a forager goes 3 steps north and 4 steps east from its nest. Which direct direction points back to the nest?',opts=['Southwest','Northeast','Southeast'],why='The outward route ends north and east of the nest. The return arrow points southwest, undoing the net displacement. This is a toy map of path integration, not evidence that a particular animal uses these exact distances.',a=panel('Outward',line(24,111,24,45,'var(--warn)',4)+line(24,45,119,45,'var(--warn)',4)+text(46,80,'3 N',11)+text(70,34,'4 E',11)+text(24,132,'Nest')+text(119,29,'End')),b=panel('Return',circle(120,45,5)+arrow(118,48,30,108)+text(30,132,'Nest')+text(116,29,'End')),rq='On a toy map a nest lies west and south of a forager. Which direction leads directly home?',ro=['Southwest','Northeast','Southeast'],rw='West and south combine to give a southwest direction.'),
 dict(id=414,slug='zoo-behavior-daily-seasonal',title='Two kinds of journey',hook='Movements can repeat on different timescales.',q='A toy animal moves between feeding and resting places each day; another shifts region each season. Which journey is seasonal?',opts=['The regional shift','The daily return','Both daily returns'],why='The first panel shows a return between feeding and resting places within a day. The second shows a regional move between seasons. The scenarios illustrate the distinction; no real route or migration schedule is implied.',a=panel('Daily',circle(30,75,9)+circle(120,75,9,'var(--warn)')+line(43,69,107,69)+line(43,81,107,81)+text(75,121,'Same day')),b=panel('Seasonal',circle(22,75,9)+circle(128,75,9,'var(--warn)')+arrow(37,75,113,75)+text(75,121,'New season')),rq='One bird flies to a local roost each evening; another shifts regions between seasons. Which is the seasonal movement?',ro=['The regional shift','The evening roost trip','Both roost trips'],rw='A seasonal regional shift occurs on a different timescale from a daily roost trip.'),
 dict(id=416,slug='zoo-behavior-rhythm-constant',title='When the light stays on',hook='Two records are taken under a constant condition.',q='In a toy study, light is held constant. Which activity record is consistent with a continuing daily rhythm?',opts=['Activity peaks at intervals','Activity stays flat','No activity is recorded'],why='The first record has repeated activity peaks under the stipulated constant light. The second stays flat. Repetition under constant conditions is consistent with an internal rhythm, but further controls and more cycles are needed to characterize it.',a=panel('Record A',line(18,110,132,110)+line(18,35,18,110)+rect(33,68,12,42)+rect(69,68,12,42)+rect(105,68,12,42)+text(39,128,'0 h',11)+text(75,128,'24 h',11)+text(111,128,'48 h',11)),b=panel('Record B',line(18,110,132,110)+line(18,35,18,110)+line(22,81,128,81,'var(--good)',4)+text(76,132,'Time →')),rq='A toy animal shows recurring activity peaks while the light remains constant. What does this pattern support?',ro=['A continuing rhythm','No recurring activity','Proof of every animal’s schedule'],rw='Repeated peaks under a constant cue are consistent with a continuing rhythm.'),
 dict(id=417,slug='zoo-behavior-alarm-listener',title='A signal and a listener',hook='A sound is present in one toy condition.',q='In a toy comparison, a listener shelters after a call but stays exposed in the no-call condition. What differs in this stated example?',opts=['The listener’s response','The size of the shelter','The color of the speaker'],why='The two panels show the same shelter but different stipulated listener locations after the cue. The comparison illustrates a possible listener response; it is not a field measurement and does not establish that all calls have the same effect.',a=panel('Call',text(35,43,'Call')+arrow(54,56,93,56)+rect(79,77,47,30,'var(--warn)')+bird(102,91)+text(102,127,'Shelter')),b=panel('No call',bird(36,91)+rect(79,77,47,30,'var(--warn)')+text(102,127,'Shelter')),rq='In a toy test, a listener changes location after hearing a cue. What is being recorded?',ro=['The listener’s behavior','The speaker’s body size','The listener’s age'],rw='The stated observation is the listener’s change in location.'),
 dict(id=420,slug='zoo-behavior-display-toy-conflict',title='Two border encounters',hook='A display can be compared with a physical contest.',q='In a toy record, one border encounter ends after a call; another continues to physical contact. Which encounter has no contact in the stated record?',opts=['The call encounter','The contact encounter','Both have contact'],why='The call panel ends with the two animals apart. The other panel shows contact. This is a stipulated comparison of two possible outcomes, not proof that territorial calls always prevent fights.',a=panel('Call',bird(35,80)+bird(115,80)+text(75,58,'♪')+text(75,124,'Apart')),b=panel('Contact',bird(63,80)+bird(84,80)+text(76,124,'Touch')),rq='Two toy animals call and then remain apart. What is observed?',ro=['A call without contact','A physical contest','No signal'],rw='The record states a call and separation, not physical contact.'),
 dict(id=429,slug='zoo-behavior-bee-uv-pattern',title='A flower beyond our view',hook='The flower is recorded in two channels.',q='A toy flower reflects the same visible color across its petals but has a contrasting ultraviolet pattern. Which sensor could detect the UV contrast?',opts=['A UV-sensitive sensor','A visible-only sensor','An unplugged sensor'],why='The visible-only panel represents uniform visible reflectance; the UV panel marks a contrasting region. The colors are false-color illustrations of signals, not a picture of a bee’s subjective experience. Some bees have UV-sensitive photoreceptors.',a=panel('Visible',flower(75,73,'var(--warn)')+text(75,126,'Uniform')),b=panel('UV channel',flower(75,73,'var(--fg)')+text(75,126,'Contrast')),rq='A sensor detects UV light but another responds only to visible light. Which can register a UV-only pattern?',ro=['The UV-sensitive sensor','The visible-only sensor','Neither sensor'],rw='The UV-sensitive sensor can register a UV signal; this does not show subjective perception.'),
 dict(id=431,slug='zoo-behavior-electric-field-cue',title='A cue without a silhouette',hook='A hidden animal can produce more than visual cues.',q='A toy scene has concealed prey that produces a weak electric field. Which cue is available to an electroreceptive predator in this model?',opts=['The electric field','A visible silhouette','A scent-free shadow'],why='The prey outline is hidden below the sediment, while curves indicate a stipulated electric field. Some fishes can detect weak electric fields with specialized receptors; the drawing is a schematic, not a measurement of detection range.',a=panel('Visual view',rect(12,89,128,22,'var(--warn)')+text(76,64,'Prey hidden')+text(76,132,'Sediment')),b=panel('Field cue',rect(12,89,128,22,'var(--warn)')+shark(37,48)+circle(76,99,5,'var(--fg)')+f'<path d="M45 82 Q76 42 107 82 M55 88 Q76 62 97 88" stroke="var(--good)" strokeWidth="3" fill="none"/>'+text(76,132,'Schematic field')),rq='A toy predator detects a field around hidden prey. What is the cue in that scenario?',ro=['An electric field','The prey’s visible color','A measured distance'],rw='The model stipulates an electric field as the available cue.'),
 dict(id=435,slug='zoo-behavior-hidden-or-warning',title='Conceal or advertise?',hook='Two defenses can affect detection in different ways.',q='In a toy scene, one animal matches its background while another has a contrasting warning pattern. Which is harder to see against that background?',opts=['The matching animal','The contrasting animal','Both patterns are identical'],why='The first animal is drawn with the same pattern as its background; the second has a contrasting pattern. Concealment and warning are different ideas. The toy scene shows visibility, not an actual predator’s behavior or the effectiveness of either defense.',a=panel('Matching',rect(14,36,124,74,'var(--warn)')+f'<ellipse cx="76" cy="73" rx="30" ry="18" fill="var(--warn)" stroke="var(--bg-2)" strokeDasharray="3 4"/>'+text(76,132,'Outline dotted')),b=panel('Contrasting',rect(14,36,124,74,'var(--warn)')+f'<ellipse cx="76" cy="73" rx="30" ry="18" fill="var(--bg-2)"/>'+text(76,132,'Visible outline')),rq='In a toy scene, which pattern blends into a striped background?',ro=['A matching stripe pattern','A sharply contrasting pattern','A label outside the picture'],rw='Matching the depicted background reduces visual contrast in this toy example.'),
 dict(id=444,slug='zoo-behavior-object-or-tool',title='An object can do a job',hook='How an object is used matters to the description.',q='In a toy observation, animal A moves a stick aside; animal B uses a stick to pull food within reach. Which action is an example of tool use under this stated definition?',opts=['Using the stick to reach food','Moving the stick aside','Both actions are identical'],why='In panel A, the stick is moved aside. In panel B, the stick helps bring food within reach. Under this lesson’s operational definition, the second action is tool use; a real study would need sufficient evidence about how the object is used.',a=panel('A: move',mouse(30,82)+line(43,85,94,85,'var(--warn)',5)+arrow(65,68,110,68)),b=panel('B: reach',mouse(30,82)+line(43,84,111,84,'var(--warn)',5)+circle(119,84,8)+arrow(118,59,69,59)),rq='An animal uses a twig to pull an out-of-reach item closer. Under the stated definition, what is the twig doing?',ro=['Serving as a tool','Moving without a role','Showing the animal’s age'],rw='The twig serves a role in reaching the item under the stated definition.'),
]
assert len(cases)==12 and len({c['id'] for c in cases})==12
outroot=Path('src/demos/life'); existing=[str(outroot/c['slug']) for c in cases if (outroot/c['slug']).exists()]
if existing: raise SystemExit('Refusing overwrite: '+', '.join(existing))
source='Unverified research lead; confirm exact claim and species with an independent source reviewer: OpenStax Biology 2e, Behavioral Biology, https://openstax.org/books/biology-2e/pages/45-7-behavioral-biology ; where applicable consult a specialist source. The illustrated observations and values are stipulated toy examples.'
template='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model = __MODEL__;
export default function Demo({slug}:{slug:string}) {
  const [seen,setSeen] = useState([false,false]);
  const seenRef = useRef([false,false]);
  function open(index:0|1, interact:()=>void) {
    if (seenRef.current[index]) return;
    seenRef.current[index] = true;
    setSeen([...seenRef.current]);
    interact();
  }
  return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} minInteractions={2} exploreHint="Open both panels and compare the evidence." reveal={()=><p>{model.explanation}</p>}>
  {({locked,interact})=><div>
    <svg viewBox="0 0 340 184" className="stage-svg" role="img" aria-label={seen[0] && seen[1] ? model.explanation : "Two evidence panels. Open both to compare."}>
      <text x="170" y="22" textAnchor="middle" fill="var(--fg)" fontSize="13">__HEADER__</text>
      <rect x="4" y="33" width="154" height="148" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="182" y="33" width="154" height="148" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
      <g transform="translate(6 37)">{seen[0] ? <g>__A__</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel A</text>}</g>
      <g transform="translate(184 37)">{seen[1] ? <g>__B__</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel B</text>}</g>
    </svg>
    <Row><Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[0]} onClick={()=>open(0,interact)}>Open A</Control><Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[1]} onClick={()=>open(1,interact)}>Open B</Control></Row>
    <p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>Illustrative model · not observed data</p>
  </div>}
  </Lesson>;
}
'''
manifest=[]
for c in cases:
 shift=c['id']%3;opts=c['opts'][shift:]+c['opts'][:shift];ans=opts.index(c['opts'][0]);rs=(c['id']+1)%3;ro=c['ro'][rs:]+c['ro'][:rs];ra=ro.index(c['ro'][0]);slug=c['slug'];p=outroot/slug;p.mkdir(parents=True)
 model={'question':c['q'],'options':opts,'answer':ans,'explanation':c['why']}
 demo=template.replace('__MODEL__',json.dumps(model,ensure_ascii=False,indent=2)).replace('__A__',c['a']).replace('__B__',c['b']).replace('__HEADER__', 'Constant light · toy record' if c['id']==416 else 'False-color channels' if c['id']==429 else 'Illustrative comparison')
 (p/'Demo.tsx').write_text(demo)
 recall={'question':c['rq'],'options':ro,'answer':ra,'why':c['rw']}
 meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals can respond to cues and conditions.'],'doesNotKnow':[c['q']]},'misconception':'The stated evidence implies a different interpretation or a universal conclusion.','objective':c['q'],'claims':[{'id':f'life.{slug}.c1','text':c['q']+' '+c['why'],'support':'source','source':source,'status':'unverified'},{'id':f'life.{slug}.c2','text':'The panels show a stipulated illustrative model and do not depict observed data.','support':'convention','source':'Diagram and model convention.','status':'unverified'},{'id':f'life.{slug}.c3','text':c['rq']+' '+c['rw'],'support':'source','source':source,'status':'unverified'}],'confidence':'','recall':recall,'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 (p/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n');manifest.append({'plan_id':c['id'],'slug':slug})
Path('company/reviews/zoology-sensory-second/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('Built',len(cases),'draft lessons')
